// Tests creating an index and then retrieving it.
// Verifies that all index properties are correctly stored and retrieved,
// including name, description, limits, and hash algorithm.
#[rstest]
#[tokio_shared_rt::test]
async fn test_create_and_get_index(#[context] ctx: Context) {
    let data = data(false).await;
    let datastore = &data.0;
    let idx_name = index_name(&ctx);

    let index = create_sample_index(&idx_name);

    // Test creating an index
    let create_result = datastore.create_index(index.clone()).await;
    assert!(
        create_result.is_ok(),
        "{}",
        format!(
            "Index creation should succeed: {}",
            create_result.unwrap_err()
        )
    );

    // Test getting the index
    let retrieved_index = datastore
        .get_index(&idx_name)
        .await
        .expect("Failed to get index");
    assert_eq!(retrieved_index.name, index.name);
    assert_eq!(retrieved_index.description, index.description);
    assert_eq!(
        retrieved_index.max_bulk_operations,
        index.max_bulk_operations
    );
    assert_eq!(retrieved_index.max_key_length, index.max_key_length);
    assert_eq!(retrieved_index.max_value_length, index.max_value_length);
    assert_eq!(
        retrieved_index.max_kv_pairs_per_context,
        index.max_kv_pairs_per_context
    );
    assert_eq!(retrieved_index.hash_algorithm, index.hash_algorithm);
    assert!(retrieved_index.created_at.is_some());
    assert_eq!(retrieved_index.created_by, index.created_by);
    assert_eq!(retrieved_index.updated_at, index.updated_at);
    assert_eq!(retrieved_index.updated_by, index.updated_by);

    // Test that creating an index with the same name fails with invalid index error.
    let duplicate_result = datastore.create_index(index.clone()).await;
    assert!(
        duplicate_result.is_err(),
        "Creating index with duplicate name should fail"
    );
}

/// Tests creating an entry between a unique key and a context.
/// Under 1:1 semantics create_entry is idempotent: a second call with the same
/// context returns the pre-existing key rather than inserting a new row.
#[rstest]
#[tokio_shared_rt::test]
async fn test_create_entry(#[context] ctx: Context) {
    let data = data(false).await;
    let datastore = &data.0;
    let _pool = &data.1;
    let idx_name = index_name(&ctx);

    let index = create_sample_index(&idx_name);
    let context = create_sample_context("test_hash_1");
    let candidate_key = Uuid::new_v4();

    // Create prerequisite index
    datastore
        .create_index(index)
        .await
        .expect("Failed to create index");

    let entry = Entry {
        key: candidate_key,
        context: context.clone(),
        index_name: idx_name.clone(),
    };

    // Test creating an entry — returns the stored key.
    let stored_key = datastore
        .create_entry(entry)
        .await
        .expect("Entry creation should succeed");
    assert_eq!(
        stored_key, candidate_key,
        "First create should use the candidate key"
    );

    // Verify the entry was created correctly by retrieving it.
    let retrieved_entry = datastore
        .get_entry_by_key(stored_key)
        .await
        .expect("Failed to retrieve created entry");

    assert_eq!(retrieved_entry.key, stored_key);
    assert_eq!(retrieved_entry.context.hash, context.hash);
    assert_eq!(retrieved_entry.context.pairs.len(), context.pairs.len());
    assert_eq!(retrieved_entry.context.pairs[0].key, "name");
    assert_eq!(retrieved_entry.context.pairs[1].key, "count");
    assert_eq!(retrieved_entry.index_name, idx_name);

    // Verify the context values are correct
    if let Some(ref name_value) = retrieved_entry.context.pairs[0].value {
        if let Some(udex_api::entry::value::Value::StringValue(ref s)) = name_value.value {
            assert_eq!(s, "test_value");
        } else {
            panic!("Expected string value for name");
        }
    } else {
        panic!("Expected value for name");
    }

    if let Some(ref count_value) = retrieved_entry.context.pairs[1].value {
        if let Some(udex_api::entry::value::Value::IntValue(i)) = count_value.value {
            assert_eq!(i, 42);
        } else {
            panic!("Expected int value for count");
        }
    } else {
        panic!("Expected value for count");
    }

    // Idempotent: a second create with the same context returns the existing key.
    let duplicate_entry = Entry {
        key: Uuid::new_v4(), // different candidate key — should be ignored
        context: context.clone(),
        index_name: idx_name.clone(),
    };
    let idempotent_key = datastore
        .create_entry(duplicate_entry)
        .await
        .expect("Idempotent create should succeed");
    assert_eq!(
        idempotent_key, stored_key,
        "Duplicate context should return the pre-existing key"
    );
}

