/// Tests retrieving the single entry for a context hash.
/// Under 1:1 semantics a context maps to at most one entry.
/// Returns None when no entry exists, Some(entry) when one does.
#[rstest]
#[tokio_shared_rt::test]
async fn test_get_entry_by_context(#[context] ctx: Context) {
    let data = data(false).await;
    let datastore = &data.0;
    let _pool = &data.1;
    let idx_name = index_name(&ctx);

    let index = create_sample_index(&idx_name);
    let context = create_sample_context("test_hash_3");

    datastore
        .create_index(index)
        .await
        .expect("Failed to create index");

    // No entry yet — expect None.
    let result = datastore
        .get_entry_by_context(&idx_name, &context.hash)
        .await
        .expect("query should succeed");
    assert!(
        result.is_none(),
        "Expected None before any entry is created"
    );

    let key = Uuid::new_v4();
    let stored_key = datastore
        .create_entry(Entry {
            key,
            context: context.clone(),
            index_name: idx_name.clone(),
        })
        .await
        .expect("Failed to create entry");

    // Exactly one entry — expect Some.
    let result = datastore
        .get_entry_by_context(&idx_name, &context.hash)
        .await
        .expect("Failed to get entry by context");
    let entry = result.expect("Expected Some after creating entry");
    assert_eq!(entry.key, stored_key);
    assert_eq!(entry.context.hash, context.hash);
    assert_eq!(entry.index_name, idx_name);

    // Verify the context values are correct
    if let Some(ref name_value) = entry.context.pairs[0].value {
        if let Some(udex_api::entry::value::Value::StringValue(ref s)) = name_value.value {
            assert_eq!(s, "test_value");
        } else {
            panic!("Expected string value for name");
        }
    } else {
        panic!("Expected value for name");
    }
}

/// Tests deleting an entry by key.
/// Verifies that the entry is removed and the context slot is freed so
/// a subsequent create with the same context produces a fresh key.
#[rstest]
#[tokio_shared_rt::test]
async fn test_delete_entry(#[context] ctx: Context) {
    let data = data(false).await;
    let datastore = &data.0;
    let idx_name = index_name(&ctx);

    let index = create_sample_index(&idx_name);
    let context = create_sample_context("test_hash_5");
    let key = Uuid::new_v4();

    // Create prerequisite data
    datastore
        .create_index(index)
        .await
        .expect("Failed to create index");

    let stored_key = datastore
        .create_entry(Entry {
            key,
            context: context.clone(),
            index_name: idx_name.clone(),
        })
        .await
        .expect("Failed to create entry");

    // Verify entry exists before deletion
    let retrieved = datastore
        .get_entry_by_key(stored_key)
        .await
        .expect("Failed to get entry before deletion");
    assert_eq!(retrieved.key, stored_key);
    assert_eq!(retrieved.context.hash, context.hash);

    // Delete the entry
    datastore
        .delete_entry(&idx_name, stored_key)
        .await
        .expect("Deleting entry should succeed");

    // Verify the entry is gone by key
    let not_found = datastore.get_entry_by_key(stored_key).await;
    assert!(
        not_found.is_err(),
        "Deleted entry should not be found by key"
    );

    // Verify the entry is gone by context
    let by_ctx = datastore
        .get_entry_by_context(&idx_name, &context.hash)
        .await
        .expect("query failed");
    assert!(
        by_ctx.is_none(),
        "Deleted entry should not be found by context"
    );

    // Re-creating with the same context after deletion produces a fresh key.
    let new_key = Uuid::new_v4();
    let re_stored = datastore
        .create_entry(Entry {
            key: new_key,
            context: context.clone(),
            index_name: idx_name.clone(),
        })
        .await
        .expect("Re-create after delete should succeed");
    assert_eq!(
        re_stored, new_key,
        "Re-created entry should use the new candidate key"
    );
    assert_ne!(
        re_stored, stored_key,
        "Re-created key should differ from the deleted key"
    );
}

